import 'package:flutter/material.dart';
import 'package:http/http.dart' as http;
import 'dart:convert';
class L extends StatefulWidget{const L({super.key});@override State<L> createState()=>_S();}
class _S extends State<L>{List items=[];
  Future<void> load()async{final r=await http.get(Uri.parse('{{endpoint}}'));setState(()=>items=jsonDecode(r.body));}
  @override void initState(){super.initState();load();}
  @override Widget build(BuildContext c)=>RefreshIndicator(onRefresh:load,child:ListView.builder(itemCount:items.length,itemBuilder:(_,i)=>ListTile(title:Text(items[i]['title'].toString()))));}
